from taf.sbts.oam.coam.admin import admin

from robot.libraries.BuiltIn import BuiltIn

from taf.ul.kpi_selector.operations.sw_update.classical_sw_update.SwUpdateFactory import SwUpdateFactory
from taf.ul.kpi_selector.operations.site_reset.classical_site_reset.SiteResetFactory import SiteResetFactory
from taf.ul.kpi_selector.operations.sw_activation.classical_sw_activation.SwActivationFactory import SwActivationFactory
from taf.ul.kpi_selector.operations.sw_rollback.classical_sw_rollback.SwRollbackFactory import SwRollbackFactory
from taf.ul.kpi_selector.operations.snapshot_collection.classical_snapshot_collection.SnapshotCollectionFactory import \
    SnapshotCollectionFactory
from taf.ul.kpi_selector.operations.reset_rf.classical_reset_rf.ResetRfFactory import ResetRfFactory
from taf.ul.kpi_selector.operations.reset_cu.classical_reset_cu.ResetCuFactory import ResetCuFactory
from taf.ul.kpi_selector.operations.rf_lock.classical_rf_lock.RfLockFactory import RfLockFactory
from taf.ul.kpi_selector.operations.rf_unlock.classical_rf_unlock.RfUnlockFactory import RfUnlockFactory
from taf.ul.kpi_selector.operations.bts_cold_startup.classical_bts_cold_startup.BtsColdStartupFactory import \
    BtsColdStartupFactory
from taf.ul.kpi_selector.operations.cell_lock.classical_cell_lock.CellLockFactory import CellLockFactory
from taf.ul.kpi_selector.operations.cell_unlock.classical_cell_unlock.CellUnlockFactory import CellUnlockFactory
from taf.ul.kpi_selector.operations.cell_block.classical_cell_block.CellBlockFactory import CellBlockFactory
from taf.ul.kpi_selector.operations.cell_unblock.classical_cell_unblock.CellUnblockFactory import CellUnblockFactory
from taf.ul.kpi_selector.operations.gsm_rat_reset.classical_gsm_rat_reset.GsmRatResetFactory import GsmRatResetFactory
from taf.ul.kpi_selector.operations.wcdma_rat_reset.classical_wcdma_rat_reset.WcdmaRatResetFactory import \
    WcdmaRatResetFactory
from taf.ul.kpi_selector.operations.lte_rat_reset.classical_lte_rat_reset.LteRatResetFactory import LteRatResetFactory
from taf.ul.kpi_selector.operations.nr_rat_reset.classical_nr_rat_reset.NrRatResetFactory import NrRatResetFactory
from taf.ul.kpi_selector.utilities.exceptions import NotSupportedOperation
from taf.ul.kpi_selector.utilities.kpi_logger.logger import log_deprecation


class kpi_selector(object):
    """ Class representing kpi operation """

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self.classical_factories = {
            "bts_cold_startup": BtsColdStartupFactory,
            "cell_block": CellBlockFactory,
            "cell_unblock": CellUnblockFactory,
            "cell_lock": CellLockFactory,
            "cell_unlock": CellUnlockFactory,
            "reset_cu": ResetCuFactory,
            "reset_rf": ResetRfFactory,
            "rf_lock": RfLockFactory,
            "rf_unlock": RfUnlockFactory,
            "site_reset": SiteResetFactory,
            "snapshot_collection": SnapshotCollectionFactory,
            "sw_activation": SwActivationFactory,
            "sw_rollback": SwRollbackFactory,
            "sw_update": SwUpdateFactory,
            "gsm_rat_reset": GsmRatResetFactory,
            "wcdma_rat_reset": WcdmaRatResetFactory,
            "lte_rat_reset": LteRatResetFactory,
            "nr_rat_reset": NrRatResetFactory
        }
        self.cloud_factories = {}
        self.operation = None
        self._tl = None

    def get_kpi(self, operation, tl=None, ran_type='Classical', *args, **kwargs):
        """
        Gets kpi for BTS operations.
        :param operation: operation for which we want to get kpi;
                          Currently supported operations for ran_type Classical:
                          bts_cold_startup, site_reset, sw_update, sw_activation, sw_rollback, snapshot_collection,
                          rf_lock, rf_unlock, reset_rf, cell_lock, cell_unlock, cell_block, cell_unblock, reset_cu,
                          gsm_rat_reset, wcdma_rat_reset, lte_rat_reset, nr_rat_reset;
                          Currently supported operations for ran_type Cloud:
                          -
        :type operation: str
        :param tl: testline object from init file or None; If None then value of tl variable will be taken via BuiltIn;
                   None by default;
        :type tl: taf.config.testline.testline.TestLine or None
        :param ran_type: can be Classical or Cloud; defaults to Classical
        :type ran_type: str
        :param args: positional arguments which will be passed to get_kpi method for desired operation; e.g.
                     /SOME/CELL/DIST/NAME-1 for operation cell_block
        :type args: tuple
        :param kwargs: keyword arguments which will be passed to get_kpi method for desired operation; e.g.
                       coverage=Full for operation snapshot_collection, inter_release=True for sw_update or
                       sw_activation
        :type kwargs: dict
        :return: dictionary with timeout, requirement and operation description for operation
        :rtype: dict
        """
        factories = self.classical_factories if ran_type == "Classical" else self.cloud_factories

        try:
            self.operation = factories[operation]()

        except KeyError:
            raise NotSupportedOperation("'{}' operation on ran_type {} is not supported by KPI Selector."
                                        .format(operation, ran_type))

        self._tl = tl
        self.operation.setup_bts(
            tl=self.tl,
            connection=self._get_default_admin_connection_alias()
        )

        return self.operation.get_kpi(*args, **kwargs)

    @property
    def tl(self):
        if self._tl is None:
            log_deprecation("Testline object was not provided in tl argument for get_kpi method. "
                            "As taf.ul.kpi_selector will be independent from robotframework in the future please "
                            "adjust calls of `get_kpi` methods and provide them with `tl` argument.")
            self._tl = BuiltIn().get_variable_value('${tl}')
        return self._tl

    def close_connections(self):
        """
        Closes admin connection to bts.
        """
        ad = admin()
        ad.teardown(connection=self._get_default_admin_connection_alias())

    @staticmethod
    def _get_default_admin_connection_alias():
        return 'admin_connection_kpi_selector'
